import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import JobList from './components/JobList';
import JobDetails from './components/JobDetails'; // Create this component

const App = () => {
    return (
        <Router>
            <div className="app-container">
                <header className="app-header">
                    <img src={logo} alt="Student Job Tracker Logo" className="app-logo" />
                    <h1>Student Job Tracker</h1>
                </header>
                <main>
                    <Switch>
                        <Route path="/" exact component={JobList} />
                        <Route path="/job/:id" component={JobDetails} /> {/* Job details route */}
                    </Switch>
                </main>
                <footer className="app-footer">
                    <p>&copy; 2023 Student Job Tracker. All rights reserved.</p>
                </footer>
            </div>
        </Router>
    );
};

export default App;
